export function validateCT_LayoutNode(value: unknown, path = 'CT_LayoutNode'): ValidationResult {
  const issues: ValidationIssue[] = [];
  if (value === null || typeof value !== 'object') return [issue(path, 'invalid-value', 'expected an object')];
  const v = value as Record<string, unknown>;
  if (!Array.isArray(v['content'])) {
  } else {
    for (let i = 0; i < (v['content'] as readonly unknown[]).length; i += 1) {
      if ((v['content'] as readonly unknown[])[i] && typeof (v['content'] as readonly unknown[])[i] === 'object') {
        const item = (v['content'] as readonly unknown[])[i] as { kind?: unknown; value?: unknown };
        if (item.kind !== '$raw') {
          if (item.kind === 'alg') issues.push(...validateCT_Algorithm(item.value, path + '.content[' + i + ']' + '.value'));
          if (item.kind === 'shape') issues.push(...validateCT_Shape(item.value, path + '.content[' + i + ']' + '.value'));
          if (item.kind === 'presOf') issues.push(...validateCT_PresentationOf(item.value, path + '.content[' + i + ']' + '.value'));
          if (item.kind === 'constrLst') issues.push(...validateCT_Constraints(item.value, path + '.content[' + i + ']' + '.value'));
          if (item.kind === 'ruleLst') issues.push(...validateCT_Rules(item.value, path + '.content[' + i + ']' + '.value'));
          if (item.kind === 'varLst') issues.push(...validateCT_LayoutVariablePropertySet(item.value, path + '.content[' + i + ']' + '.value'));
          if (item.kind === 'forEach') issues.push(...validateCT_ForEach(item.value, path + '.content[' + i + ']' + '.value'));
          if (item.kind === 'layoutNode') issues.push(...validateCT_LayoutNode(item.value, path + '.content[' + i + ']' + '.value'));
          if (item.kind === 'choose') issues.push(...validateCT_Choose(item.value, path + '.content[' + i + ']' + '.value'));
          if (item.kind === 'extLst') issues.push(...validateCT_OfficeArtExtensionList(item.value, path + '.content[' + i + ']' + '.value'));
          if ('alg' !== item.kind && 'shape' !== item.kind && 'presOf' !== item.kind && 'constrLst' !== item.kind && 'ruleLst' !== item.kind && 'varLst' !== item.kind && 'forEach' !== item.kind && 'layoutNode' !== item.kind && 'choose' !== item.kind && 'extLst' !== item.kind) issues.push(issue(path + '.content[' + i + ']', 'invalid-value', 'unknown choice alternative'));
        }
      }
    }
  }
  if (v['name'] === undefined) {
  } else {
    if (!validBuiltin(v['name'], 'xsd:string')) issues.push(issue(path + '.name', 'invalid-value', 'invalid xsd:string'));
  }
  if (v['styleLbl'] === undefined) {
  } else {
    if (!validBuiltin(v['styleLbl'], 'xsd:string')) issues.push(issue(path + '.styleLbl', 'invalid-value', 'invalid xsd:string'));
  }
  if (v['chOrder'] === undefined) {
  } else {
    issues.push(...validateST_ChildOrderType(v['chOrder'], path + '.chOrder'));
  }
  if (v['moveWith'] === undefined) {
  } else {
    if (!validBuiltin(v['moveWith'], 'xsd:string')) issues.push(issue(path + '.moveWith', 'invalid-value', 'invalid xsd:string'));
  }
  return issues;
}

